import { useState } from "react";
import { AppProvider, useApp } from "./context/AppContext";
import GirisEkrani from "./pages/GirisEkrani";
import AdminPanel from "./pages/admin/AdminPanel";
import IlanlarSayfasi from "./pages/kamyoncu/IlanlarSayfasi";
import KamyoncuProfil from "./pages/kamyoncu/ProfilSayfasi";
import { SeferlerSayfasi, MesajlarSayfasi } from "./pages/kamyoncu/DigerSayfalar";
import { IlanVerSayfasi, TekliflerSayfasi, IssizProfilSayfasi } from "./pages/issiz/IssizSayfalar";
import { Header, BottomNav } from "./components/UI";
import "./index.css";

function MobilApp() {
  const { oturum } = useApp();
  const [sekme, setSekme] = useState(oturum.rol === "kamyoncu" ? "ilanlar" : "ilanver");

  const kamyoncuSayfalar = {
    ilanlar:  <IlanlarSayfasi />,
    seferler: <SeferlerSayfasi />,
    mesajlar: <MesajlarSayfasi />,
    profil:   <KamyoncuProfil />,
  };
  const issizSayfalar = {
    ilanver:   <IlanVerSayfasi />,
    teklifler: <TekliflerSayfasi />,
    mesajlar:  <MesajlarSayfasi />,
    profil:    <IssizProfilSayfasi />,
  };

  const sayfalar = oturum.rol === "kamyoncu" ? kamyoncuSayfalar : issizSayfalar;

  return (
    <div className="app-shell">
      <Header />
      <div>{sayfalar[sekme]}</div>
      <BottomNav aktif={sekme} setAktif={setSekme} rol={oturum.rol} />
    </div>
  );
}

function AppIcerigi() {
  const { oturum } = useApp();
  if (!oturum) return <GirisEkrani />;
  if (oturum.rol === "admin") return <AdminPanel />;
  return <MobilApp />;
}

export default function App() {
  return (
    <AppProvider>
      <AppIcerigi />
    </AppProvider>
  );
}
